using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "VoidSmithAnimationData", menuName = "Data/Animation/VoidSmithAnimationData")]
public class VoidSmithAnimationData : CustomAnimationData
{
	[SerializeField]
	private AphoticInstinctEffect aphoticInstinctEffect;

	public override AnimationType GetCustomAttackAnimationType(SpriteControl spriteControl, EnemySFXData enemySFXData)
	{
		if (enemySFXData.EnableEnemyAttackDelay)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enemySFXData.EnemyAttackDelay, delegate
			{
				enemySFXData.PlayEnemyAttackSFX();
			});
		}
		else
		{
			enemySFXData.PlayEnemyAttackSFX();
		}
		return aphoticInstinctEffect.GetAnimationType(spriteControl.GetComponent<UnitEffects>(), "Attack");
	}
}
